const test = require("node:test");
const assert = require("node:assert");
const { add, divide, average, percent, roundTo } = require("./calc");

test("add", () => assert.strictEqual(add(2, 3), 5));
test("divide", () => assert.strictEqual(divide(10, 4), 2.5));
test("divide by zero throws", () => assert.throws(() => divide(1, 0), /zero/));
test("average", () => assert.strictEqual(average([2, 4, 6]), 4));
test("average of empty list is 0", () => assert.strictEqual(average([]), 0));
test("percent", () => assert.strictEqual(percent(25, 200), 12.5));
test("roundTo", () => assert.strictEqual(roundTo(3.14159, 2), 3.14));

